using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Media.DeleteMedia;public sealed class DeleteMediaCommandHandler(IMediaReferenceRepository repo,IContentAuditService audit,IUnitOfWork uow):ICommandHandler<DeleteMediaCommand,Result>{public async Task<Result> HandleAsync(DeleteMediaCommand c,CancellationToken ct=default){var x=await repo.GetByIdAsync(c.Id,ct);if(x is null||x.IsDeleted)return Result.Failure(ContentErrors.MediaNotFound);var before=ContentAuditSnapshots.From(x);x.Delete(c.ActorUserId);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.MediaDeleted,ContentAuditActions.Deleted,ContentAuditEntityTypes.MediaReference,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x),Payload:new{x.StorageFileId}),ct);await uow.SaveChangesAsync(ct);return Result.Success();}}
